import React, { Component } from 'react'
import {
  View,
  Text,
  StyleSheet,
  TouchableOpacity,
  Dimensions,
  Image,
  TouchableNativeFeedback,
  BackHandler,
  ScrollView
} from 'react-native';
import { DrawerActions } from 'react-navigation-drawer';
import { ListItem, Icon } from 'react-native-elements';

const screen = Dimensions.get('window');
  vh = screen.height / 100;
  vw = screen.width / 100;


const items = [
  { name: 'one'},
  { name: 'two'},
  //{ name: 'three'}
]

class ItemList extends Component {

  static navigationOptions = {
    header: null
  }

  constructor() {
    super();
    this.handleBackButton = this.handleBackButton.bind(this);
    this.state = {
      streak: 0,
      buttons: [
        'CONCEPT GYM',
        //'CHALLENGE',
        'PRACTICE TEST',
      ],
      links: [
        'gym',
        //'challenge',
        'new_test',
      ],
      backgrounds: [
        'data:image/png;base64,',
        //'data:image/png;base64,',
        'data:image/png;base64,',
      ],
      about: [
        'Build your concept in topics, step by step with unlimited questions.',
        //'Challenge your friends.',
        'Create and practice your tests based on topics, subjects and goal.',
      ]
    }
  }

  handleBackButton() {
    this.props.navigation.navigate('Home');
    return true;
  }

  componentWillUnmount() {
    BackHandler.removeEventListener('hardwareBackPress', this.handleBackButton);
  }

  componentDidMount() {
    BackHandler.addEventListener('hardwareBackPress', this.handleBackButton);
  }

  render () {
    return (
      <View style={styles.container}>
      <View style={{flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', width: '100%', height: 8 * vh, backgroundColor: '#ffffff'}}>
        <View style={{justifyContent:'flex-start', marginLeft:10}}>
        <Icon           
          name='menu'
          color='#7741cd'
          type='material'
          size= {35} 
          onPress={() => this.props.navigation.dispatch(DrawerActions.toggleDrawer())}
          />
        </View>
        <View style={{marginLeft:0}}>
          <Text style={{fontFamily: 'Montserrat-SemiBold', fontSize: 3 * vh, color: '#7741cd'}}> Playground </Text>
        </View>
        <View style={{justifyContent:'flex-end', marginRight: 10}}>
        <Icon
          name='notifications'
          color='#7741cd'
          type='material'
          size= {35} 
          onPress={() => this.props.navigation.navigate('notification', { title: "Notification" })}
          />
        </View>

      </View>

      <ScrollView style={{width: '100%', marginTop: '7%', marginBottom: 7 * vh}}>
        {
          this.state.buttons.map((button, index) => (
            <TouchableNativeFeedback
                    onPress={() => {
                      this.props.navigation.navigate(this.state.links[index])
                    }
                }

               >
              <View style={{flexDirection: 'row', alignItems: 'center', justifyContent: 'center', alignSelf: 'center', elevation: 2, marginBottom: 4 * vh, borderRadius: 2 * vw, padding: 2 * vw, backgroundColor: '#ffffff'}}>
                <View style={[styles.largeButton]}>
                  <Image
                    style={{
                      width: '100%',
                      height: '100%',
                      zIndex: 0,
                    }}
                    resizeMode={'cover'}
                    source={{uri: this.state.backgrounds[index]}}
                  />
                </View>
                  <View style={styles.aboutTextContainer}>
                    <Text style={[styles.buttonText, styles.largeButtonText, {fontFamily: 'Proxima Nova Bold'}]}>
                      {button}
                    </Text>
                    <Text style={styles.aboutText}>
                      {this.state.about[index]}
                    </Text>
                  </View>
              </View>
          </TouchableNativeFeedback>
          ))
        }
        </ScrollView>
      </View>
    )
  }
}

export default ItemList

